"""pt — virtues_c."""

T = {
"virtues_051": ("O que aconselha Luqman ao seu filho a respeito da voz?", ["Baixar a voz: a mais detestável é a do burro", "Falar muito alto", "Nunca falar", "Cantar ao caminhar"], "«Sê moderado no teu andar e baixa a tua voz: a mais detestável das vozes é a do burro»."),
"virtues_052": ("Que três recomendações dá Luqman ao seu filho antes de falar da paciência?", ["Estabelecer a oração, ordenar o bem, proibir o mal", "Viajar, comerciar, escrever", "Comer pouco, dormir pouco, falar pouco", "Construir, plantar, colher"], "«Ó meu filho, estabelece a oração, ordena o bem, proíbe o mal e tem paciência perante o que te suceder»."),
"virtues_053": ("Que três qualidades atribui o Alcorão aos piedosos, na sura Al 'Imran?", ["Gastar na abundância e na estreiteza, conter a ira, perdoar às pessoas", "Jejuar, velar, calar", "Construir, plantar, dar", "Viajar, aprender, ensinar"], "«Os que gastam na abundância e na estreiteza, contêm a ira e perdoam às pessoas: Allah ama os que fazem o bem»."),
"virtues_054": ("O que considera o Alcorão melhor do que uma esmola seguida de uma ofensa?", ["Uma palavra amável e um perdão", "Um dom maior", "Um silêncio total", "Um juramento"], "«Uma palavra amável e um perdão valem mais do que uma esmola seguida de agravo»."),
"virtues_055": ("O que diz o Alcorão da esmola dada em segredo?", ["É melhor para quem a dá", "Não conta", "Deve ser anunciada", "É proibida"], "«Se derdes esmolas publicamente, está bem; mas se as ocultardes e as derdes aos pobres, é melhor para vós»."),
"virtues_056": ("De que proíbe o Alcorão dar esmola?", ["Daquilo que o próprio só aceitaria fechando os olhos", "Do que é novo", "Do que se ama", "Do que vem de uma herança"], "«E não escolhais o pior disso para gastar, quando vós próprios não o aceitaríeis senão fechando os olhos»."),
"virtues_057": ("Quando se alcança a verdadeira piedade, segundo a sura Al 'Imran?", ["Gastando daquilo que se ama", "Gastando o que sobra", "Gastando em público", "Guardando tudo"], "«Não alcançareis a piedade até gastardes daquilo que amais»."),
"virtues_058": ("Que imagem emprega o Alcorão para o equilíbrio no gasto?", ["Não manter a mão presa ao pescoço nem estendê-la por completo", "Fechar a porta", "Andar devagar", "Contar duas vezes"], "«Não leves a tua mão presa ao pescoço, nem a estendas por completo, pois ficarias censurado e desprovido»."),
"virtues_059": ("Como descreve o Alcorão o gasto dos «servos do Clemente»?", ["Nem esbanjadores nem avarentos, mas no justo meio", "Sempre generosos sem medida", "Sempre poupados", "Sem nunca dar"], "«E aqueles que, quando gastam, não esbanjam nem são avarentos, mas se mantêm num justo meio»."),
"virtues_060": ("O que ordena o Alcorão antes de entrar numa casa que não é a sua?", ["Pedir licença e saudar os seus habitantes", "Bater três vezes e entrar", "Entrar diretamente", "Chamar de longe"], "«Não entreis em casas alheias sem terdes pedido licença e saudado os seus habitantes»."),
"virtues_061": ("O que fazer se se pedir ao visitante que se vá embora, segundo a sura An-Nur?", ["Voltar: é mais puro para si", "Insistir", "Esperar à porta", "Entrar na mesma"], "«E se vos disserem: “Voltai”, voltai: é mais puro para vós»."),
"virtues_062": ("O que ordena o Alcorão quando alguém pouco fiável traz uma notícia?", ["Verificá-la, para que ninguém seja prejudicado por ignorância", "Difundi-la logo", "Escrevê-la", "Ignorá-la sempre"], "«Se um perverso vos trouxer uma notícia, verificai-a, para que não prejudiqueis pessoas por ignorância e depois vos arrependais»."),
"virtues_063": ("Que conduta, a par da maledicência, proíbe a sura Al-Hujurat?", ["Espiar e suspeitar em excesso", "Viajar sozinho", "Falar baixo", "Escrever cartas"], "«Ó crentes! Evitai muitas suspeitas: algumas suspeitas são pecado. E não espieis nem faleis mal uns dos outros»."),
"virtues_064": ("O que ordena o Alcorão quando dois grupos de crentes combatem entre si?", ["Reconciliá-los com equidade", "Tomar partido", "Ignorá-los", "Separá-los só pela força"], "«Se dois grupos de crentes combaterem entre si, reconciliai-os… e sede equitativos: Allah ama os equitativos»."),
"virtues_065": ("O que proíbe expressamente o Alcorão, mesmo em relação a um povo que se detesta?", ["Que o ódio afaste da justiça", "O comércio", "A palavra", "A vizinhança"], "«Que o ódio por um povo não vos leve a ser injustos. Sede justos: isso está mais perto da piedade»."),
"virtues_066": ("Contra quem exige o Alcorão testemunhar com equidade, se for preciso?", ["Contra si próprio, contra os pais e os parentes", "Só contra os estranhos", "Só contra os ricos", "Só contra os pobres"], "«Sede firmes na justiça, testemunhas perante Allah, ainda que seja contra vós próprios, contra os vossos pais ou os vossos parentes»."),
"virtues_067": ("O que ordena o Alcorão devolver aos seus legítimos donos?", ["Os depósitos confiados (amanat)", "As cartas", "As colheitas", "Os relatos"], "«Allah ordena-vos devolver os depósitos aos seus donos e que, quando julgardes entre os homens, julgueis com equidade»."),
"virtues_068": ("Que pessoas enumera o versículo 4:36 para o bom trato, depois dos pais?", ["Os parentes, os órfãos, os pobres, o vizinho próximo e o distante, o companheiro, o viajante e o servo", "Os reis e os chefes", "Os comerciantes", "Só os sábios"], "«Adorai Allah e nada Lhe associeis. Sede bons com os vossos pais, com os parentes, os órfãos, os pobres, o vizinho próximo e o vizinho distante, o companheiro de viagem, o viajante e aqueles que as vossas mãos direitas possuem»."),
"virtues_069": ("O que ordena o Alcorão em relação a um devedor em dificuldade?", ["Conceder-lhe um prazo até à folga", "Persegui-lo", "Duplicar a dívida", "Expulsá-lo"], "«E se estiver em dificuldade, concedei-lhe um prazo até a um momento de folga; mas perdoar é melhor para vós»."),
"virtues_070": ("O que ordena o versículo mais longo do Alcorão a respeito de uma dívida a prazo?", ["Pô-la por escrito", "Mantê-la em segredo", "Esquecê-la", "Transmiti-la oralmente"], "«Ó crentes! Quando contrairdes uma dívida por um prazo determinado, ponde-a por escrito»."),
"virtues_071": ("O que proíbe o Alcorão a respeito dos bens alheios?", ["Devorá-los injustamente, ou usá-los para subornar os juízes", "Contá-los", "Vendê-los", "Guardá-los"], "«Não devoreis injustamente os vossos bens uns dos outros, nem os ofereçais aos juízes para devorardes com pecado parte dos bens das pessoas»."),
"virtues_072": ("O que ordena o Alcorão a respeito dos bens dos órfãos?", ["Entregar-lhos, sem trocar o bom pelo mau", "Reparti-los", "Vendê-los", "Retê-los para sempre"], "«Dai aos órfãos os seus bens; não substituais o mau pelo bom nem consumais os seus bens junto com os vossos»."),
"virtues_073": ("Como ordena o Alcorão medir e pesar?", ["Dar a medida completa e pesar com balança justa", "Arredondar em benefício próprio", "Pesar a olho", "Medir duas vezes"], "«E dai a medida completa quando medirdes, e pesai com balança justa: isso é melhor e de melhor resultado»."),
"virtues_074": ("O que proíbe seguir o Alcorão, por falta de conhecimento?", ["Aquilo de que não se tem conhecimento: o ouvido, a vista e o coração responderão", "O caminho mais curto", "As caravanas", "O silêncio"], "«Não sigas aquilo de que não tens conhecimento: o ouvido, a vista e o coração, de tudo isso se será perguntado»."),
"virtues_075": ("Que imagem dá o Alcorão do orgulho no andar?", ["Não se pode fender a terra nem alcançar a altura das montanhas", "Avança-se mais depressa", "Cansa-se menos", "Faz-se respeitar"], "«E não andes pela terra com arrogância: não poderás fender a terra nem alcançar a altura das montanhas»."),
"virtues_076": ("Que qualidade da palavra ordena o Alcorão, prometendo que as obras serão retificadas?", ["Uma palavra justa e reta (qawl sadid)", "Uma palavra breve", "Uma palavra erudita", "Uma palavra escrita"], "«Ó crentes! Temei Allah e dizei uma palavra justa: Ele retificará as vossas obras e perdoar-vos-á os pecados»."),
"virtues_077": ("Que espécie de palavra foi ordenada mesmo perante um tirano, no Alcorão?", ["Uma palavra suave", "Uma palavra ameaçadora", "Uma palavra irónica", "O silêncio"], "«E falai-lhe com palavras suaves: talvez se recorde ou tema»."),
"virtues_078": ("De quem diz o Alcorão que tem a melhor palavra?", ["De quem chama a Allah, pratica o bem e diz: sou dos muçulmanos", "Do poeta", "Do orador", "Do juiz"], "«E quem diz melhor palavra do que quem chama a Allah, pratica o bem e diz: certamente, sou dos muçulmanos?»"),
"virtues_079": ("Do que se afastam os crentes que triunfam, segundo Al-Mu'minun?", ["Do vão (al-laghw)", "Do trabalho", "Das viagens", "Das refeições"], "«…e aqueles que se afastam do vão»."),
"virtues_080": ("Que dois encargos guardam os crentes que triunfam, segundo Al-Mu'minun?", ["Os depósitos que lhes são confiados e os seus compromissos", "O jejum e a vigília", "A viagem e o comércio", "A escrita e a leitura"], "«E aqueles que cuidam dos depósitos que lhes são confiados e dos seus compromissos»."),
"virtues_081": ("O que diz o Alcorão de quem perdoa e reconcilia, podendo devolver o mal?", ["A sua recompensa incumbe a Allah", "Perde o seu direito", "É censurado", "Deve calar-se"], "«A retribuição de uma má ação é outra má ação igual; mas quem perdoar e reconciliar, a sua recompensa incumbe a Allah»."),
"virtues_082": ("Que argumento dá o Alcorão para perdoar a quem nos agravou?", ["«Não amais que Allah vos perdoe?»", "«Sereis compensados com dinheiro»", "«Tornar-vos-á poderosos»", "«Poupar-vos-á um processo»"], "«Que perdoem e desculpem. Não amais que Allah vos perdoe? Allah é Perdoador, Misericordioso»."),
"virtues_083": ("Que três instruções reúne o versículo 7:199?", ["Aceitar o que é dado de bom grado, ordenar o bem e afastar-se dos ignorantes", "Combater, fugir, calar", "Comer, beber, dormir", "Contar, escrever, ler"], "«Aceita o que é dado de bom grado, ordena o bem e afasta-te dos ignorantes»."),
"virtues_084": ("Que atitude recomenda o Alcorão perante as palavras ofensivas e a provação?", ["A paciência e a piedade: isso é dos assuntos que exigem determinação", "A réplica imediata", "A retirada definitiva", "O silêncio desdenhoso"], "«Ouvireis muitas ofensas dos que receberam o Livro antes de vós. Mas se fordes pacientes e temerosos, isso é dos assuntos que exigem determinação»."),
"virtues_085": ("Como qualifica o Alcorão a paciência e o perdão?", ["São dos assuntos que exigem determinação", "São fraqueza", "São opcionais", "São só para os sábios"], "«E quem tem paciência e perdoa, certamente isso é dos assuntos que exigem determinação»."),
"virtues_086": ("Para quem diz o Alcorão que a oração não é um fardo pesado?", ["Para os humildes perante Allah (al-khashi'in)", "Para os ricos", "Para os sábios", "Para os viajantes"], "«Buscai auxílio na paciência e na oração: certamente é pesada, salvo para os humildes»."),
"virtues_087": ("O que recorda o Alcorão sobre o que se detesta ou o que se ama?", ["Pode que detestes algo que é um bem, e ames algo que é um mal", "O que amas é sempre bom", "O que detestas é sempre mau", "Sabes sempre o que é bom"], "«Pode que detesteis algo que é um bem para vós, e pode que ameis algo que é um mal para vós. Allah sabe e vós não sabeis»."),
"virtues_088": ("O que promete o Alcorão a quem teme Allah, quanto a saída e sustento?", ["Uma saída e um sustento de onde não espera", "Riqueza imediata", "Uma longa viagem", "Um cargo público"], "«A quem teme Allah, Ele dá uma saída e provê-o de onde não espera»."),
"virtues_089": ("Que gratidão ordena o Alcorão a par da gratidão a Allah?", ["A gratidão para com os pais", "Para com o senhor", "Para com o vizinho", "Para com o rei"], "«Sê grato para comigo e para com os teus pais: para Mim é o retorno»."),
"virtues_090": ("Que limite põe o Alcorão à obediência aos pais?", ["Não lhes obedecer se ordenarem associar algo a Allah", "Nunca lhes obedecer", "Obedecer-lhes em tudo", "Obedecer-lhes só em viagem"], "«E se ambos te esforçarem a associar-Me algo de que não tens conhecimento, não lhes obedeças; mas trata-os neste mundo com bondade»."),
"virtues_091": ("Que súplica ensina o Alcorão a respeito dos pais e da descendência?", ["Agradecer o favor, praticar o bem e que a descendência seja retificada", "Pedir riqueza", "Pedir uma longa viagem", "Pedir um cargo"], "«Senhor meu, inspira-me a agradecer o favor com que me agraciaste a mim e aos meus pais, e a praticar o bem; e retifica para mim a minha descendência»."),
"virtues_092": ("O que pedem «os servos do Clemente» a respeito da sua família?", ["Que seja alegria dos olhos, e serem exemplo para os piedosos", "Que seja rica", "Que seja numerosa", "Que viaje"], "«Senhor nosso, concede-nos das nossas esposas e descendência alegria dos olhos, e faz de nós exemplo para os piedosos»."),
"virtues_093": ("Como se comportam «os servos do Clemente» perante o vão?", ["Passam adiante com dignidade", "Param para escutar", "Respondem com vivacidade", "Escrevem-no"], "«E aqueles que não dão falso testemunho e que, quando passam junto ao vão, passam com dignidade»."),
"virtues_094": ("O que ordena o Alcorão numa reunião quando se pede lugar?", ["Dar lugar: Allah dar-vos-á lugar", "Permanecer apertados", "Sair", "Calar"], "«Ó crentes! Quando vos for dito: “Dai lugar nas reuniões”, dai-o: Allah dar-vos-á lugar»."),
"virtues_095": ("Com quem ordena o Alcorão estar, na sura At-Tawba?", ["Com os verazes", "Com os poderosos", "Com os ricos", "Com os viajantes"], "«Ó crentes! Temei Allah e estai com os verazes»."),
"virtues_096": ("Com quem ordena o Alcorão ao Profeta ﷺ manter-se com paciência, em Al-Kahf?", ["Com os que invocam o seu Senhor de manhã e à tarde, desejando a Sua face", "Com os chefes de tribo", "Com os ricos comerciantes", "Com os poetas"], "«Mantém-te com paciência junto aos que invocam o seu Senhor de manhã e à tarde, desejando a Sua face; e que os teus olhos não se afastem deles»."),
"virtues_097": ("Em que ordena o Alcorão ajudarem-se mutuamente, e em que o proíbe?", ["Ajudar-se na piedade e no bem, não no pecado e na agressão", "Ajudar-se em tudo", "Não se ajudar com ninguém", "Ajudar-se só em família"], "«Ajudai-vos uns aos outros na virtude e na piedade, e não vos ajudeis no pecado e na agressão»."),
"virtues_098": ("O que ordena o Alcorão a respeito do pacto concluído e dos juramentos confirmados?", ["Cumprir o pacto e não quebrar os juramentos depois de os ter confirmado", "Renegociá-los", "Esquecê-los", "Ocultá-los"], "«Cumpri o pacto de Allah quando o tiverdes firmado, e não quebreis os juramentos depois de os terdes confirmado»."),
"virtues_099": ("Segundo um hadice narrado por al-Bukhari, quando é completa a fé de um homem?", ["Quando ama para o seu irmão o que ama para si próprio", "Quando jejua o ano inteiro", "Quando dá todos os seus bens", "Quando viaja a Meca"], "«Nenhum de vós crê verdadeiramente até amar para o seu irmão o que ama para si próprio»."),
"virtues_100": ("Em que casos vê o Alcorão bem nas conversas privadas?", ["Ordenar uma esmola, uma boa ação ou uma reconciliação entre as pessoas", "Tratar de negócios", "Preparar uma viagem", "Contar notícias"], "«Não há bem em muitas das suas conversas secretas, salvo em quem ordena uma esmola, algo bom ou a reconciliação entre as pessoas»."),
}
